      for (const m of ALL) plan[m]=(plan[m]||[]).flatMap(it=>{ if (it.fk!=="cinnamon"||it._user||over<=0.02) return [it]; const cut=Math.min(it.g,over); over-=cut; const ng=Math.round((it.g-cut)*10)/10; return ng<0.2?[]:[{...it,g:ng}]; });
      for (const m of ALL) for (const it of [...(plan[m]||[])]) { if (cinDay()<=CIN_MAX+0.02) break; const f=TEMP_FDB[it.fk]; if (it._user||!f||!f._isRecipe||!(cinOf(it)>0)) continue;
        const sv=f._servingG||200, n=Math.round(it.g/sv); if (n>=2) plan[m][plan[m].indexOf(it)]={...it,g:Math.round((n-1)*sv*100)/100}; }
