    if ((fd.cat==="אגוזים"||fd.cat==="זרעים") && !isCountedPiece(it.fk)) return null; // מותר חלקי — מטופל בצעדים עדינים למטה
    const whole = fd.cat==="אגוזים"||fd.cat==="פרי"||BREAD.has(it.fk)||(su.count||1)>1||/יחידה|פרוסה|חופן/.test(su.he||"");
