    const occ=[]; daysArr.forEach((d,di)=>Object.keys(d).forEach(mk=>(d[mk]||[]).forEach((x,idx)=>{ if(x&&x.fk===fk&&!x._keep&&!x._user) occ.push({di,mk,idx,dup:Object.values(d).flat().filter(y=>y&&y.fk===fk).length}); })));
