          if (fd.cat==="פרי") { const su=getServingUnit(it.fk,fd,"he"); const oneUnitG=su&&!su.weightOnly&&su.g?su.g/(su.count||1):it.g; if (it.g>=oneUnitG-0.5) continue; }
