        const rawNewG = item.g - reduceBy;
        // לעולם לא משאירים וואקמה בכמות שביר-כפית זעירה (מתחת לרבע כפית) — או מסירים לגמרי, או מעגלים לרבע כפית הקרוב ביותר
        item.g = rawNewG < wakameQtrStepG*0.5 ? 0 : Math.round(rawNewG/wakameQtrStepG)*wakameQtrStepG;
