      if ((ct.sodium||0) + addSodium > sodiumCap + 0.5) break;
      const mk = plan.lunch ? "lunch" : Object.keys(plan)[0];
      if (!mk) break;
      const existing = plan[mk].find(it=>it.fk==="nori");
      if (existing) existing.g = Math.round((existing.g+NORI_G_PER_SHEET)*100)/100;
      else plan[mk].push({fk:"nori", g:NORI_G_PER_SHEET});
