      const addSodium = wakamePer100b.sodium * WAKAME_QTR_TSP_G/100;
      if ((ct.sodium||0) + addSodium > sodiumCap + 0.5) break;
      const mk = plan.lunch ? "lunch" : Object.keys(plan)[0];
      if (!mk) break;
