function capVegUnitsPerMeal(day){
  ["breakfast","lunch","dinner"].forEach(mk=>{
    if (!day[mk]) return;
    let items = day[mk];
    const vegIdxs = items.map((it,idx)=>({it,idx})).filter(({it})=>{
      const fd = FDB[it.fk]; return fd && !fd._isRecipe && fd.cat==="ירק";
    });
    let totalUnits = 0;
    vegIdxs.forEach(({it})=>{
      const fd = FDB[it.fk];
      const su = getServingUnit(it.fk, fd, "he");
      if (su && !su.weightOnly && su.g) totalUnits += Math.max(1, Math.round(it.g/(su.g/(su.count||1))));
      else totalUnits += 1;
    });
    if (totalUnits <= 2) return;
    // חיתוך פשוט וודאי: מסירים פריטי-ירק החל מהקטן ביותר עד שנשארות לכל היותר 2 יחידות בסך הכל — לא מנסים
    // להחליף בסלט כאן (זה כבר קורה בשכבה הפנימית, כשהיא כן פועלת) — רק מבטיחים שלעולם לא יישארו יותר מ-2
    const sorted = [...vegIdxs].sort((a,b)=>ingNut(a.it.fk,a.it.g).kcal-ingNut(b.it.fk,b.it.g).kcal);
    let remaining = totalUnits;
    const dropIdxSet = new Set();
    for (const {it,idx} of sorted) {
      if (remaining<=2) break;
      const fd = FDB[it.fk];
      const su = getServingUnit(it.fk, fd, "he");
      const units = (su && !su.weightOnly && su.g) ? Math.max(1, Math.round(it.g/(su.g/(su.count||1)))) : 1;
      dropIdxSet.add(idx);
      remaining -= units;
    }
    if (dropIdxSet.size) day[mk] = items.filter((it,idx)=>!dropIdxSet.has(idx));
  });
}
