function pieceStepG(fk){ const u=PIECE_UNITS[fk]; return u?u.g*(u.grid||1):null; }
// כמות מיושרת לרשת היחידה (לפחות צעד אחד) — גם לתצוגה של פריט שלא עבר יישור (מתכנן אישי / הוספה ידנית)
// min: כמות מזערית שיש בה טעם (לא "פיסטוק אחד") — פחות ממחציתה מושמט (0), אחרת מוגדל אליה
function snapPieceG(fk,g,noMin){ const st=pieceStepG(fk); if(!st||!(g>0)) return g; let n=Math.max(1,Math.round(g/st)); const mn=noMin?1:(PIECE_UNITS[fk].min||1);
  if (n<mn) n=(g/st<mn/2)?0:mn; return Math.round(n*st*100)/100; }
// יחידת תצוגה לפריט בתפריט: יחידת-חתיכה אם הוגדרה, אחרת יחידת ההגשה הרגילה
function displayUnit(fk,fd,lang){ return (fd&&!fd._isRecipe&&PIECE_UNITS[fk])||getServingUnit(fk,fd,lang); }
function displayQtyG(fk,fd,g){ return fd&&!fd._isRecipe&&PIECE_UNITS[fk]?snapPieceG(fk,g,true):g; }
function getServingUnit(fk,fd,lang){
  if(SERVING_UNITS[fk]) return SERVING_UNITS[fk];
  if(!fd) return null;
  if(__SU_OVERRIDES[fk]) return __SU_OVERRIDES[fk];
  const cat=fd.cat;
  return __SU_DEFAULTS[cat]||null;
}

function servingLabel(fk,g,lang){
  const fd=FDB[fk]||TEMP_FDB[fk]; const u=displayUnit(fk,fd,lang); const gr=lang==="he"?"ג׳":"g"; if(u&&PIECE_UNITS[fk]) g=displayQtyG(fk,fd,g);
  if(!u){
    const cat=fd?.cat||"";
    let fallbackHe="",fallbackEn="",baseG=100;
    if(cat==="עלים"){fallbackHe="כוס";fallbackEn="cup";baseG=30;}
    else if(cat==="ירק"){fallbackHe="יח׳ בינונית";fallbackEn="medium";baseG=100;}
    else if(cat==="פרי"){fallbackHe="יח׳ בינונית";fallbackEn="medium";baseG=120;}
    else if(cat==="קטנית"){fallbackHe="כוס מבושל";fallbackEn="cup (cooked)";baseG=165;}
    else if(cat==="דגן"){fallbackHe="כוס מבושל";fallbackEn="cup (cooked)";baseG=160;}
    else if(cat==="זרעים"){fallbackHe="כף";fallbackEn="tbsp";baseG=10;}
    else if(cat==="אגוזים"){fallbackHe="חופן";fallbackEn="handful";baseG=28;}
    else if(cat==="שומן"){fallbackHe="כף";fallbackEn="tbsp";baseG=15;}
    else if(cat==="חלבון"){fallbackHe="כוס";fallbackEn="cup";baseG=240;}
    else{return `${g}${gr}`;}
    const ratio=g/baseG;
    const count=Math.abs(ratio-1)<0.1?"":Math.abs(ratio-0.5)<0.1?"½ ":Math.abs(ratio-2)<0.1?"2 ":fmtN(ratio,1)+" ";
    return `${count}${lang==="he"?fallbackHe:fallbackEn} (${g}${gr})`;
  }
  const ratio=g/u.g;
  const count=Math.abs(ratio-1)<0.1?"":Math.abs(ratio-0.5)<0.1?"½ ":Math.abs(ratio-2)<0.1?"2 ":Math.abs(ratio-0.25)<0.05?"¼ ":fmtN(ratio,1)+" ";
  const label=unitWord(u,ratio,lang);
  return `${count}${label} (${g}${gr})`;
}

