  const per=tot/Math.max(1,r.servings); const scale=Math.min(1,ONEPLATE_KCAL_MAX*0.98/per)*(srv/Math.max(1,r.servings)); // 2% מרווח לעיגול // מנה ≤400, ומספר מנות srv
