// מספרים, אפשר לראות אם המצב טוב, גבולי, או גבוה. thresholds הוא [ירוק-עד, צהוב-עד] — מעל השני = אדום.
function triColor(value,thresholds){
  const[greenMax,yellowMax]=thresholds;
  if(value<=greenMax) return "#2e7d32";
  if(value<=yellowMax) return "#b8860b";
  return "#c62828";
}


