const REST_CANDS=["soymilkFortified","tofu","edamame","chickpeas","whiteBeans","lupinBeansCooked","greenLentils","blackBeans","tempeh",
  "almonds","sunflowerS","pumpkinS","hazelnuts","cashews","peanuts","walnuts","broccoli","bokChoy","kale","spinach","redPepper","sweetPotatoCooked","quinoaCooked","kiwi","orange","banana","avocado"];
function restAddG(fk){ const f=FDB[fk]; if(!f) return 0;
  if (fk==="pumpkinS"||fk==="sunflowerS") return 10; if (f.cat==="אגוזים") return 15;
  if (fk==="soymilkFortified") return 240; if (f.cat==="קטנית") return 85; if (f.cat==="עלים") return 60;
  return getServingUnit(fk,f,"he")?.g||100; }
function restMealFor(fk){ const c=FDB[fk]?.cat; if (fk==="soymilkFortified"||c==="אגוזים"||c==="זרעים") return ["breakfast","snack"];
  if (c==="פרי") return ["snack","breakfast"]; return ["lunch","dinner"]; }
