        const s0=shortOf(proj()), p0=proj()[k]||0, t0=tots[i]; let best=null;
        for (const fk of cands){ if (!(FDB[fk].per100?.[k]>0)) continue;
          const trial=tryAdd(daysArr[i],fk,orig[i]); yield {phase:"weekly",n:++n}; if(!trial) continue;
          if (changedItems(orig[i],trial)>maxCh) continue;
          const tt=dayT(trial); if (!safe(i,trial,tt)) continue;
          tots[i]=tt; const P=proj(); const gain=((P[k]||0)-p0)/W(k)*100; const sh=shortOf(P); tots[i]=t0;
          if (gain>=1 && sh<s0-1e-6 && (!best||gain>best.gain)) best={trial,gain}; }
        if (best){ daysArr[i]=best.trial; tots[i]=dayT(best.trial); improved=true; }
